package com.rikkeibank.transaction.controller; import com.rikkeibank.transaction.dto.TransferRequest; import com.rikkeibank.transaction.model.BankTransaction; import com.rikkeibank.transaction.model.TransactionEntry; import com.rikkeibank.transaction.service.TransactionService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/transactions") public class TransactionController{private final TransactionService s;public TransactionController(TransactionService s){this.s=s;}@PostMapping("/transfers") @PreAuthorize("hasAnyRole('CUSTOMER','ADMIN')") public ResponseEntity<BankTransaction> transfer(@Valid @RequestBody TransferRequest r,@AuthenticationPrincipal Jwt jwt){return ResponseEntity.status(201).body(s.transfer(r,jwt.getSubject()));}@GetMapping("/{id}/entries") @PreAuthorize("hasAnyRole('ADMIN','TELLER')") public List<TransactionEntry> entries(@PathVariable Long id){return s.entries(id);}@GetMapping("/me") @PreAuthorize("hasRole('CUSTOMER')") public List<BankTransaction> mine(@AuthenticationPrincipal Jwt jwt){return s.history(jwt.getSubject());}@GetMapping("/today") @PreAuthorize("hasRole('TELLER')") public List<BankTransaction> today(@AuthenticationPrincipal Jwt jwt){return s.todayForTeller(jwt.getSubject());}@PutMapping("/{id}/assign/{teller}") @PreAuthorize("hasRole('ADMIN')") public BankTransaction assign(@PathVariable Long id,@PathVariable String teller){return s.assign(id,teller);}@PostMapping("/{id}/review") @PreAuthorize("hasRole('TELLER')") public BankTransaction review(@PathVariable Long id,@AuthenticationPrincipal Jwt jwt){return s.review(id,jwt.getSubject());}}
